"""Build the one-page Ethical Compliance Declaration for the HCL submission.

HCL's deliverables list asks for a "Signed Ethical Compliance Declaration". The four statements are the
ones in the synopsis template (section 9). Each is followed by concrete lines on how this project meets
it; the facts come from docs/PROJECT_REPORT.md section 14 and Appendix A.

Learner name, roll number, signature and date stay blank for the learner.

Run:  .venv\\Scripts\\python.exe docs\\build\\build_declaration.py
Output: submission/Ethical_Compliance_Declaration.docx
"""
from __future__ import annotations

from pathlib import Path

from docx import Document
from docx.enum.table import WD_TABLE_ALIGNMENT
from docx.enum.text import WD_ALIGN_PARAGRAPH
from docx.oxml import OxmlElement
from docx.oxml.ns import qn
from docx.shared import Cm, Pt, RGBColor

ROOT = Path(__file__).resolve().parents[2]
OUT = ROOT / "submission" / "Ethical_Compliance_Declaration.docx"

FONT = "Calibri"
INK = RGBColor(0x1F, 0x1F, 0x1F)
ACCENT = RGBColor(0x3D, 0x1A, 0x6E)
GREY = RGBColor(0x55, 0x55, 0x55)

STATEMENTS = [
    (
        "All dataset usage complies with the source licence.",
        [
            "The 500 rows supplied by HCL are used under the terms of the programme folder they came in. "
            "They stay unchanged in data/dataset_original.csv, with the original labels.",
            "The other 4,500 rows are generated by this project's own script (generate_dataset.py), so no "
            "third-party licence applies to them. No real customer data was collected.",
        ],
    ),
    (
        "No personally identifiable information (PII) is stored without consent.",
        [
            "The data has no names, phone numbers, email or street addresses. The only identifier is a "
            "pseudonymous customer_id such as C00001; age is an age band (youngest 18-25, so no minors) and "
            "location is one of five regions.",
            "The smallest age-band by region group holds 76 customers, so no combination points to a few people. "
            "The rows are synthetic or HCL's anonymised teaching data.",
        ],
    ),
    (
        "AI tools used for code/writing are disclosed in the Appendix.",
        [
            "Claude (Anthropic) was used as a coding assistant to write and run the Python pipeline, the EDA "
            "notebook and the React and TypeScript app, and to draft the report, the synopsis and the README "
            "(Appendix A of the project report).",
            "Every number in the report comes from a script run on this project's files. The learner is "
            "responsible for understanding and explaining the code and the results.",
        ],
    ),
    (
        "This project complies with the DPDP Act 2023 where applicable.",
        [
            "Consent before marketing: consent is kept per customer. The campaign builder counts the audience "
            "before and after the consent check and contacts only consented customers; a campaign with no "
            "consented audience is not sent. Each grant or withdrawal is one action and is written to a consent "
            "log (customer id, granted or withdrawn, source, time).",
            "Right to erasure and access: the Privacy and Consent screen has an erase action that removes the "
            "customer from the data in use and records an audit event. A customer's profile and the CSV export "
            "give the record on request.",
            "Data stays on the device: the app has no server and sends no customer data over the network.",
        ],
    ),
]


def run(par, text, bold=False, italic=False, size=11, color=INK, font=FONT):
    r = par.add_run(text)
    r.font.name = font
    r._element.rPr.rFonts.set(qn("w:eastAsia"), font)
    r.font.size = Pt(size)
    r.bold = bold or None
    r.italic = italic or None
    r.font.color.rgb = color
    return r


def fmt(par, before=0, after=0, left=None, first=None, align=None, line=1.08, keep_next=False):
    pf = par.paragraph_format
    pf.space_before, pf.space_after, pf.line_spacing = Pt(before), Pt(after), line
    if left is not None:
        pf.left_indent = Cm(left)
    if first is not None:
        pf.first_line_indent = Cm(first)
    if align is not None:
        par.alignment = align
    if keep_next:
        pf.keep_with_next = True


def bottom_rule(par, color="3D1A6E", size=12):
    ppr = par._p.get_or_add_pPr()
    borders = OxmlElement("w:pBdr")
    b = OxmlElement("w:bottom")
    for k, v in (("w:val", "single"), ("w:sz", str(size)), ("w:space", "4"), ("w:color", color)):
        b.set(qn(k), v)
    borders.append(b)
    ppr.append(borders)


def main():
    doc = Document()
    sec = doc.sections[0]
    sec.page_width, sec.page_height = Cm(21.0), Cm(29.7)
    sec.left_margin = sec.right_margin = Cm(2.0)
    sec.top_margin, sec.bottom_margin = Cm(1.6), Cm(1.4)

    normal = doc.styles["Normal"]
    normal.font.name = FONT
    normal.element.rPr.rFonts.set(qn("w:eastAsia"), FONT)
    normal.font.size = Pt(11)

    # ---- heading block
    p = doc.add_paragraph()
    fmt(p, after=2, align=WD_ALIGN_PARAGRAPH.CENTER)
    run(p, "Ethical Compliance Declaration", bold=True, size=22, color=ACCENT)
    p = doc.add_paragraph()
    fmt(p, after=6, align=WD_ALIGN_PARAGRAPH.CENTER)
    run(p, "HCLTech Career Shaper Programme | III Year Industry Project | 2025-26", italic=True, size=10.5, color=GREY)
    bottom_rule(p)

    p = doc.add_paragraph()
    fmt(p, before=4, after=1)
    run(p, "Project title: ", bold=True)
    run(p, "RetailMax CRM: Streamlining Customer Relationships")
    p = doc.add_paragraph()
    fmt(p, after=6)
    run(p, "Project No.: ", bold=True)
    run(p, "27")

    # ---- learner fields
    t = doc.add_table(rows=1, cols=4)
    t.style = "Table Grid"
    t.alignment = WD_TABLE_ALIGNMENT.CENTER
    widths = [Cm(3.2), Cm(5.8), Cm(3.2), Cm(4.8)]
    for cell, w, (txt, bold) in zip(t.rows[0].cells, widths,
                                    [("Learner Name", True), ("[FILL IN]", False), ("Roll Number", True), ("[FILL IN]", False)]):
        cell.width = w
        cp = cell.paragraphs[0]
        fmt(cp, before=2, after=2)
        run(cp, txt, bold=bold, size=10.5)
        if bold:
            shd = OxmlElement("w:shd")
            shd.set(qn("w:val"), "clear")
            shd.set(qn("w:color"), "auto")
            shd.set(qn("w:fill"), "ECE6F5")
            cell._tc.get_or_add_tcPr().append(shd)

    # ---- statements
    p = doc.add_paragraph()
    fmt(p, before=9, after=3, keep_next=True)
    run(p, "I confirm that:", bold=True, size=11.5)

    for stmt, lines in STATEMENTS:
        p = doc.add_paragraph()
        fmt(p, before=3, after=1, left=0.75, first=-0.75, keep_next=True)
        run(p, "☑", size=12, font="Segoe UI Symbol")
        run(p, "\t" + stmt, bold=True, size=11)
        p.paragraph_format.tab_stops.add_tab_stop(Cm(0.75))
        for ln in lines:
            b = doc.add_paragraph()
            fmt(b, after=1, left=1.4, first=-0.4, line=1.05)
            b.paragraph_format.tab_stops.add_tab_stop(Cm(1.4))
            run(b, "–\t", size=9.5, color=GREY)
            run(b, ln, size=10)

    p = doc.add_paragraph()
    fmt(p, before=6, after=0, line=1.05)
    run(p, "Scope note: ", bold=True, size=9.5, color=GREY)
    run(p, "this is a prototype. A real deployment would also need a privacy notice shown before consent is asked, "
           "server-side consent records, access control and breach handling (project report, section 14.4).",
        italic=True, size=9.5, color=GREY)

    # ---- signature block
    p = doc.add_paragraph()
    fmt(p, before=38, after=0)
    run(p, "Learner Signature: ", bold=True)
    run(p, "_" * 34 + "      ")
    run(p, "Date: ", bold=True)
    run(p, "_" * 20)

    p = doc.add_paragraph()
    fmt(p, before=14, after=0, align=WD_ALIGN_PARAGRAPH.CENTER)
    run(p, "HCLTech Career Shaper Programme 2025-26  |  RetailMax CRM, Project No. 27", italic=True, size=8.5, color=GREY)

    OUT.parent.mkdir(parents=True, exist_ok=True)
    doc.save(OUT)
    print("saved", OUT)


if __name__ == "__main__":
    main()
